// Filtra y normaliza el evento de Evolution
const body = $input.item.json.body || $input.item.json;
const event = body.event;
const data = body.data;

if (event !== 'messages.upsert') {
  return { json: { skip: true, reason: `Evento ignorado: ${event}` } };
}

if (!data) {
  return { json: { skip: true, reason: 'Sin data' } };
}

if (data.key?.fromMe === true) {
  return { json: { skip: true, reason: 'Mensaje propio (fromMe)' } };
}

const msg = data.message || {};
const messageText = msg.conversation
  || msg.extendedTextMessage?.text
  || msg.imageMessage?.caption
  || msg.videoMessage?.caption
  || '';

if (!messageText.trim()) {
  return { json: { skip: true, reason: 'Mensaje no es texto' } };
}

const remoteJid = data.key?.remoteJid || '';
const phone = remoteJid.replace('@s.whatsapp.net', '').replace('@c.us', '');
const pushName = data.pushName || null;

if (remoteJid.includes('@g.us')) {
  return { json: { skip: true, reason: 'Mensaje de grupo (ignorados en Fase 2)' } };
}

return {
  json: {
    skip: false,
    message: messageText,
    contact_phone: phone,
    contact_name: pushName,
    remoteJid,
    instance: body.instance || 'excalando',
    messageId: data.key?.id
  }
};

// Construye SQL UPSERT en conversaciones por whatsapp_number
const i = $input.item.json;

function esc(s) {
  if (s === null || s === undefined) return 'NULL';
  return "'" + String(s).replace(/'/g, "''") + "'";
}

const sql = `INSERT INTO conversaciones (whatsapp_number, customer_name, status, first_message_at, last_message_at)
VALUES (${esc(i.contact_phone)}, ${esc(i.contact_name)}, 'active', NOW(), NOW())
ON CONFLICT (whatsapp_number) DO UPDATE SET
  customer_name = COALESCE(EXCLUDED.customer_name, conversaciones.customer_name),
  last_message_at = NOW(),
  status = CASE WHEN conversaciones.status = 'resolved' THEN 'active' ELSE conversaciones.status END
RETURNING id;`;

return { json: { sql, ...i } };

// Toma el conversacion_id devuelto y enriquece el contexto
const pgResult = $input.item.json;
const original = $('Filtrar y normalizar evento').item.json;
const conversacionId = pgResult.id;

if (!conversacionId) {
  throw new Error('Postgres UPSERT no devolvio conversacion_id');
}

return {
  json: {
    ...original,
    conversacion_id: conversacionId
  }
};

// INSERT mensaje del cliente en mensajes_analisis (sin analisis IA aun, eso lo hace el Analyzer aparte)
const i = $input.item.json;

function esc(s) {
  if (s === null || s === undefined) return 'NULL';
  return "'" + String(s).replace(/'/g, "''") + "'";
}

const sql = `INSERT INTO mensajes_analisis (conversacion_id, message_id, direction, text, sentiment, emotion, intent, topics, flags, opportunity_score, risk_score, summary_es, created_at)
VALUES (${i.conversacion_id}, ${esc(i.messageId)}, ${esc('in')}, ${esc(i.message)}, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NOW());`;

return { json: { sql, ...i } };

// Toma respuesta del Conversational + datos originales y prepara:
// 1. Payload Evolution para enviar respuesta
// 2. SQLs para registrar lo que paso (UPDATE conversacion + opcional INSERT alerta)

const convResp = $input.item.json;
const original = $('Extraer conversacion_id').item.json;
const meta = convResp.metadata || {};
const convId = original.conversacion_id;

function esc(s) {
  if (s === null || s === undefined) return 'NULL';
  return "'" + String(s).replace(/'/g, "''") + "'";
}

const sqlUpdateConv = `UPDATE conversaciones SET ai_handled_count = ai_handled_count + 1, last_message_at = NOW() WHERE id = ${convId};`;

let sqlInsertAlerta = null;
if (meta.tool_called === 'escalar_a_humano' || meta.needs_human_review === true) {
  const motivo = meta.tool_args?.motivo || 'Escalacion automatica detectada';
  const urgencia = meta.tool_args?.urgencia || 'media';
  const severityMap = { alta: 'alta', media: 'media' };
  const severity = severityMap[urgencia] || 'media';

  sqlInsertAlerta = `INSERT INTO alertas (conversacion_id, tipo, severity, message, notified_via, reviewed) VALUES (${convId}, ${esc('escalation_request')}, ${esc(severity)}, ${esc(motivo)}, ARRAY['log']::text[], false);`;
}

return {
  json: {
    evolution_number: original.contact_phone,
    evolution_text: convResp.respuesta || '(no respuesta)',
    sql_update_conv: sqlUpdateConv,
    sql_insert_alerta: sqlInsertAlerta,
    needs_alerta: !!sqlInsertAlerta,
    metadata: meta,
    contact_name: original.contact_name,
    original_message: original.message
  }
};

